137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
139	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
143	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
144	        this.telephoneUniquenessValidator.validateUnique(owner.getTelephone());
145	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
146	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
147	            this.householdUniquenessValidator.validateUnique(owner.getLastName(), owner.getAddress());
148	        } else {
149	            this.householdRegistrar.assignHousehold(owner);
150	        }
151	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
152	        owner.setCustomerCode(CustomerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
153	            this.cityOwnerCounter.count(owner.getCity())));
154	        this.clinicService.saveOwner(owner);
155	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
