47	/**
48	 * Global Exception handler for REST controllers.
49	 * <p>
50	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
51	 *
52	 * @author Vitaliy Fedoriv
53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
113	     * method returns a 404 Not Found status if an entity does not exist.
114	     *
115	     * @param e The {@link DataIntegrityViolationException} to be handled
116	     * @param request {@link HttpServletRequest} object referring to the current request.
117	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
118	     */
119	    @ExceptionHandler(DataIntegrityViolationException.class)
120	    @ResponseBody
121	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
122	        logger.warn("Data integrity violation at {} {}: {}",
123	            request.getMethod(),
124	            request.getRequestURI(),
125	            e.getMessage());
126	        logger.debug("Data integrity violation stacktrace", e);
127	        HttpStatus status = HttpStatus.NOT_FOUND;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles exception thrown by Bean Validation on controller methods parameters
134	     *
135	     * @param e The {@link MethodArgumentNotValidException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
138	     */
139	    @ExceptionHandler(MethodArgumentNotValidException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
142	        HttpStatus status = HttpStatus.BAD_REQUEST;
143	        BindingErrorsResponse errors = new BindingErrorsResponse();
144	        BindingResult bindingResult = e.getBindingResult();
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
146	        List<String> fieldNames = bindingResult.getFieldErrors().stream()
147	            .map(FieldError::getField)
148	            .distinct()
149	            .toList();
150	        detail.setProperty("errors", fieldNames);
151	        if (bindingResult.hasErrors()) {
152	            errors.addAllErrors(bindingResult);
153	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
154	                .map(fieldError -> {
155	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
156	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
157	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
158	                        fieldError.getField(),
159	                        defaultMessage,
160	                        rejectedValue);
161	                    return new ValidationMessageDto(message)
162	                        .putAdditionalProperty("field", fieldError.getField())
163	                        .putAdditionalProperty("rejectedValue", rejectedValue)
164	                        .putAdditionalProperty("defaultMessage", defaultMessage);
165	                })
166	                .toList();
167	            logger.debug("Validation error at {} {}: {}",
168	                request.getMethod(),
169	                request.getRequestURI(),
170	                bindingResult.getFieldErrors());
171	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
172	            return ResponseEntity.status(status).body(detail);
173	        }
174	        return ResponseEntity.status(status).body(detail);
175	    }
176	
177	    /**
178	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created or updated with
179	     * required fields that are missing or blank. Returns a 400 Bad Request whose body carries an
180	     * {@code errors} array listing the name of each offending field.
181	     *
182	     * @param e The {@link MissingOwnerFieldsException} to be handled
183	     * @param request {@link HttpServletRequest} object referring to the current request.
184	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
185	     */
186	    @ExceptionHandler(MissingOwnerFieldsException.class)
187	    @ResponseBody
188	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
189	        HttpStatus status = HttpStatus.BAD_REQUEST;
190	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
191	        detail.setProperty("errors", e.getMissingFields());
192	        logger.debug("Missing or blank required fields at {} {}: {}",
193	            request.getMethod(),
194	            request.getRequestURI(),
195	            e.getMissingFields());
196	        return ResponseEntity.status(status).body(detail);
197	    }
198	
199	    /**
200	     * Handles {@link InvalidTelephoneException} raised when an owner's telephone cannot be converted
201	     * to a valid E.164 number ({@code '+'} followed by 8 to 15 digits). Returns a 400 Bad Request
202	     * whose body carries an {@code errors} array naming the {@code telephone} field.
203	     *
204	     * @param e The {@link InvalidTelephoneException} to be handled
205	     * @param request {@link HttpServletRequest} object referring to the current request.
206	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
207	     */
208	    @ExceptionHandler(InvalidTelephoneException.class)
209	    @ResponseBody
210	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
211	        HttpStatus status = HttpStatus.BAD_REQUEST;
212	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
213	        detail.setProperty("errors", List.of("telephone"));
214	        logger.debug("Invalid telephone at {} {}: {}",
215	            request.getMethod(),
216	            request.getRequestURI(),
217	            e.getMessage());
218	        return ResponseEntity.status(status).body(detail);
219	    }
220	
221	    /**
222	     * Handles {@link InvalidEmailException} raised when an owner's submitted email is present but
223	     * is not a syntactically valid address. Returns a 400 Bad Request whose body carries an
224	     * {@code errors} array naming the {@code email} field.
225	     *
226	     * @param e The {@link InvalidEmailException} to be handled
227	     * @param request {@link HttpServletRequest} object referring to the current request.
228	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
229	     */
230	    @ExceptionHandler(InvalidEmailException.class)
231	    @ResponseBody
232	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
233	        HttpStatus status = HttpStatus.BAD_REQUEST;
234	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
235	        detail.setProperty("errors", List.of("email"));
236	        logger.debug("Invalid email at {} {}: {}",
237	            request.getMethod(),
238	            request.getRequestURI(),
239	            e.getMessage());
240	        return ResponseEntity.status(status).body(detail);
241	    }
242	
243	    /**
244	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner is created with a
245	     * normalized telephone that is already used by another owner. Returns a 409 Conflict whose
246	     * body carries an {@code errors} array naming the {@code telephone} field.
247	     *
248	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
249	     * @param request {@link HttpServletRequest} object referring to the current request.
250	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
251	     */
252	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
253	    @ResponseBody
254	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
255	        HttpStatus status = HttpStatus.CONFLICT;
256	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
257	        detail.setProperty("errors", List.of("telephone"));
258	        logger.debug("Duplicate owner telephone at {} {}: {}",
259	            request.getMethod(),
260	            request.getRequestURI(),
261	            e.getMessage());
262	        return ResponseEntity.status(status).body(detail);
263	    }
264	
265	    /**
266	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner is created whose last
267	     * name and address already belong to another owner and the request did not opt in via
268	     * {@code sharesHousehold}. Returns a 409 Conflict whose body carries an {@code errors} array
269	     * naming the offending {@code lastName} and {@code address} fields.
270	     *
271	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
272	     * @param request {@link HttpServletRequest} object referring to the current request.
273	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
274	     */
275	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
276	    @ResponseBody
277	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
278	        HttpStatus status = HttpStatus.CONFLICT;
279	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
280	        detail.setProperty("errors", List.of("lastName", "address"));
281	        logger.debug("Duplicate owner household at {} {}: {}",
282	            request.getMethod(),
283	            request.getRequestURI(),
284	            e.getMessage());
285	        return ResponseEntity.status(status).body(detail);
286	    }
287	
288	    /**
289	     * Handles {@link CityOwnerCapacityExceededException} raised when an owner is created in a city
290	     * that has already reached its maximum number of owners. Returns a 409 Conflict whose body
291	     * carries an {@code errors} array naming the offending {@code city} field.
292	     *
293	     * @param e The {@link CityOwnerCapacityExceededException} to be handled
294	     * @param request {@link HttpServletRequest} object referring to the current request.
295	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
296	     */
297	    @ExceptionHandler(CityOwnerCapacityExceededException.class)
298	    @ResponseBody
299	    public ResponseEntity<ProblemDetail> handleCityOwnerCapacityExceededException(CityOwnerCapacityExceededException e, HttpServletRequest request) {
300	        HttpStatus status = HttpStatus.CONFLICT;
301	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
302	        detail.setProperty("errors", List.of("city"));
303	        logger.debug("City owner capacity exceeded at {} {}: {}",
304	            request.getMethod(),
305	            request.getRequestURI(),
306	            e.getMessage());
307	        return ResponseEntity.status(status).body(detail);
308	    }
309	
310	}
